extends "res://test/framework/test_case.gd"
const Priorities := preload("res://scripts/core/priorities.gd")
const Bridge := preload("res://scripts/core/save_owner_priorities.gd")
const Section := preload("res://scripts/core/save_section_component_columns.gd")
const Schema := preload("res://scripts/core/save_component_columns_schema.gd")
const COUNTS: Array[int] = [512,6144,512,512]
const KEYS: Array[String] = ["_present","_job_priority","_auto_fallback","_dangerous_work"]
const CODES: Array[StringName] = [&"COLUMN_PRESENT_BYTE",&"COLUMN_PRIORITY_RANGE",
	&"COLUMN_AUTO_FALLBACK_BYTE",&"COLUMN_DANGEROUS_WORK_BYTE"]

func _empty() -> Array[PackedByteArray]:
	"""Independent physical fixture sizes, not values read from production metadata."""
	var image: Array[PackedByteArray] = []
	for count: int in COUNTS:
		var bytes: PackedByteArray = PackedByteArray()
		bytes.resize(count)
		image.append(bytes)
	return image

func _put(image: Array[PackedByteArray], field: int, index: int, value: int) -> void:
	"""Write a packed fixture value back explicitly through its outer array."""
	var bytes: PackedByteArray = image[field]
	bytes[index] = value
	image[field] = bytes

func _base() -> Array[PackedByteArray]:
	"""A present row with nondefault policy distinguishes lost presence from empty state."""
	var image: Array[PackedByteArray] = _empty()
	_put(image,0,0,1)
	_put(image,1,1,2)
	return image

func _predicate(image: Array[PackedByteArray]) -> StringName:
	"""Invoke the owner API in independently pinned canonical field order."""
	return Priorities.columns_refusal(image[0],image[1],image[2],image[3])

func _frame(image: Array[PackedByteArray]) -> Section.FramedOwner:
	"""Copy the four caller columns into an owner11 fixture, asserting every setter."""
	var frame: Section.FramedOwner = Section.FramedOwner.new(11)
	for field: int in 4:
		assert_true(frame.set_u8(field,image[field]),"fixture field%d" % field)
	return frame

func _expect(image: Array[PackedByteArray], code: StringName) -> void:
	"""Static/framed answers agree and every caller-owned byte remains unchanged."""
	var before: Array[PackedByteArray] = []
	for bytes: PackedByteArray in image:
		before.append(bytes.duplicate())
	var frame: Section.FramedOwner = _frame(image)
	assert_equal(_predicate(image),code,"static exact code")
	var refusal: Variant = Bridge.framed_refusal(frame)
	assert_equal(refusal.code,code,"framed exact code")
	assert_equal(refusal.is_ok(),code == &"","success channel")
	if code == &"": assert_equal(refusal.detail,"","success has no detail")
	else:
		assert_true(refusal.detail.contains("11"),"failure identifies owner")
		assert_true(refusal.detail.contains(String(code)),"failure identifies exact code")
	for field: int in 4:
		assert_true(image[field] == before[field],"static input unchanged")
		assert_true(frame.u8_column(field) == before[field],"framed input unchanged")

func _from_owner(owner: Priorities) -> Array[PackedByteArray]:
	"""Use public readers to sample real lifecycle output; inactive bytes are specified zeros."""
	var image: Array[PackedByteArray] = _empty()
	for slot: int in 512:
		if not owner.is_present(slot): continue
		_put(image,0,slot,1)
		for kind: int in 12:
			var priority: Variant = owner.priority_of(slot,kind)
			assert_true(priority.ok,"public priority read succeeds")
			_put(image,1,slot*12+kind,priority.value)
		var fallback: Variant = owner.auto_fallback_of(slot)
		var dangerous: Variant = owner.dangerous_work_of(slot)
		assert_true(fallback.ok and dangerous.ok,"public policy reads succeed")
		_put(image,2,slot,fallback.value)
		_put(image,3,slot,dangerous.value)
	return image

func test_field_identity_and_all_zero_empty_frame() -> void:
	"""Pin the fixture identities independently and accept the genuine empty image."""
	for field: int in 4:
		assert_equal(Schema.field_key(11,field),KEYS[field],"field identity")
		assert_equal(Schema.field_type(11,field),0,"all columns are bytes")
		assert_equal(Schema.element_count(11,field),COUNTS[field],"physical extent")
	_expect(_empty(),&"")
	assert_true(Bridge.framed_refusal(Section.FramedOwner.new(11)).is_ok(),"zero frame is a valid empty owner")

func test_independent_projection_witnesses_and_asymmetric_flags() -> void:
	"""Exact codes kill each zero-substitution and the two swapped policy arguments."""
	for field: int in 4:
		var image: Array[PackedByteArray] = _base()
		_put(image,field,0,5 if field == 1 else 2)
		_expect(image,CODES[field])
	_expect(_base(),&"")
	var image: Array[PackedByteArray] = _base()
	_put(image,2,0,2)
	_put(image,3,0,255)
	_expect(image,&"COLUMN_AUTO_FALLBACK_BYTE")
	_put(image,2,0,0)
	_expect(image,&"COLUMN_DANGEROUS_WORK_BYTE")

func test_every_physical_priority_byte_is_checked() -> void:
	"""An invalid value in any of6144bytes must be found, including inactive rows."""
	var image: Array[PackedByteArray] = _empty()
	for index: int in 6144:
		_put(image,1,index,5)
		assert_equal(_predicate(image),&"COLUMN_PRIORITY_RANGE","range gate at physical byte%d" % index)
		_put(image,1,index,0)
	_put(image,1,6143,255)
	_expect(image,&"COLUMN_PRIORITY_RANGE")

func test_active_priority_values_and_policy_flags_are_mutable_domains() -> void:
	"""Spawn defaults cannot replace the full accepted player-choice domains."""
	for value: int in 5:
		var image: Array[PackedByteArray] = _base()
		for kind: int in 12:
			if kind != 3: _put(image,1,kind,value)
		_put(image,2,0,value%2)
		_put(image,3,0,1-value%2)
		_expect(image,&"")
	for field: int in [0,2,3]:
		var image: Array[PackedByteArray] = _base()
		_put(image,field,0,255)
		_expect(image,CODES[field])

func test_reserved_first_and_last_rows_precede_inactive_residue() -> void:
	"""Reserved storage is zero at all physical rows, whether present or inactive."""
	for slot: int in [0,511]:
		for present: int in [0,1]:
			var image: Array[PackedByteArray] = _empty()
			_put(image,0,slot,present)
			_put(image,1,slot*12+3,3)
			_expect(image,&"COLUMN_RESERVED_PRIORITY")
			_put(image,1,slot*12+3,7)
			_expect(image,&"COLUMN_PRIORITY_RANGE")

func test_free_rows_require_every_policy_and_active_kind_to_be_zero() -> void:
	"""Each retained flag or active-kind priority on an inactive row refuses."""
	for slot: int in [0,511]:
		for kind: int in 12:
			if kind == 3: continue
			var image: Array[PackedByteArray] = _empty()
			_put(image,1,slot*12+kind,1)
			_expect(image,&"COLUMN_FREE_ROW")
		for field: int in [2,3]:
			var image: Array[PackedByteArray] = _empty()
			_put(image,field,slot,1)
			_expect(image,&"COLUMN_FREE_ROW")

func test_refusal_order_across_distinct_rows() -> void:
	"""Several simultaneous problems resolve by the declared domain order."""
	var image: Array[PackedByteArray] = _empty()
	_put(image,2,511,1)
	_expect(image,&"COLUMN_FREE_ROW")
	_put(image,1,3,3)
	_expect(image,&"COLUMN_RESERVED_PRIORITY")
	_put(image,1,6143,5)
	_expect(image,&"COLUMN_PRIORITY_RANGE")
	_put(image,3,20,2)
	_expect(image,&"COLUMN_DANGEROUS_WORK_BYTE")
	_put(image,2,25,2)
	_expect(image,&"COLUMN_AUTO_FALLBACK_BYTE")
	_put(image,0,30,2)
	_expect(image,&"COLUMN_PRESENT_BYTE")
	var short: PackedByteArray = image[0]
	short.resize(511)
	image[0] = short
	assert_equal(_predicate(image),&"COLUMN_SHAPE","shape precedes every indexed read")

func test_all512_present_rows_are_legal_for_policy_storage() -> void:
	"""This owner has no living-health state and must not impose a256row cap."""
	var image: Array[PackedByteArray] = _empty()
	var present: PackedByteArray = image[0]
	present.fill(1)
	image[0] = present
	_put(image,1,511*12+11,4)
	_put(image,3,511,1)
	_expect(image,&"")

func test_public_lifecycle_and_shared_free_row_reader() -> void:
	"""Public policy changes and released rows retain the existing reader contract."""
	var owner: Priorities = Priorities.new()
	assert_false(owner.inactive_row_is_clear(-1),"negative slot refused")
	assert_false(owner.inactive_row_is_clear(512),"high slot refused")
	for slot: int in [0,511]:
		assert_true(owner.inactive_row_is_clear(slot),"new row clear")
		assert_true(owner.spawn(slot).ok,"spawn")
		assert_false(owner.inactive_row_is_clear(slot),"present row is never inactive")
		assert_true(owner.set_priority(slot,1,4).ok,"player priority")
		assert_true(owner.set_auto_fallback(slot,false).ok,"player fallback")
		assert_true(owner.set_dangerous_work(slot,true).ok,"player consent")
	_expect(_from_owner(owner),&"")
	assert_equal(owner.present_count(),2,"validation cannot alter owner count")
	for slot: int in [0,511]:
		assert_true(owner.despawn(slot).ok,"release")
		assert_true(owner.inactive_row_is_clear(slot),"all released bytes clear")
	_expect(_from_owner(owner),&"")

func test_all_column_shapes_refuse_before_semantic_access() -> void:
	"""Each ordinal requires its exact extent in both static and framed validation."""
	for field: int in 4:
		for size: int in [0,COUNTS[field]-1,COUNTS[field]+1]:
			var image: Array[PackedByteArray] = _base()
			var bytes: PackedByteArray = image[field]
			bytes.resize(size)
			image[field] = bytes
			assert_equal(_predicate(image),&"COLUMN_SHAPE","static extent")
			var frame: Section.FramedOwner = _frame(_base())
			frame.u8_columns[field] = bytes
			assert_equal(Bridge.framed_refusal(frame).code,&"SAVE_COMPONENT_SHAPE","framed extent")

func test_null_wrong_owner_and_bucket_counts_refuse() -> void:
	"""Malformed framing stops before typed accessor arguments are evaluated."""
	assert_equal(Bridge.framed_refusal(null).code,&"SAVE_COMPONENT_SHAPE","null record")
	for owner: int in [-1,9,18]:
		assert_equal(Bridge.framed_refusal(Section.FramedOwner.new(owner)).code,&"SAVE_COMPONENT_OWNER","wrong owner")
	for variant: int in 4:
		var frame: Section.FramedOwner = _frame(_base())
		if variant == 0: frame.u8_columns.pop_back()
		elif variant == 1: frame.u8_columns.append(PackedByteArray())
		elif variant == 2: frame.i32_columns.append(PackedInt32Array())
		else: frame.i64_columns.append(PackedInt64Array())
		assert_equal(Bridge.framed_refusal(frame).code,&"SAVE_COMPONENT_SHAPE","exact typed buckets")

#!/usr/bin/env python3
"""Exercise owner11 metadata gates and bypasses in an owned disposable Godot clone.

Counterfactual field type/count tables rebalance all affected lengths, including the
compiled expected total, to reach gate4 with a valid schema. They are not production
format changes. Source-capacity/generator checks separately pin the real schema.
"""
import ast
import hashlib
import json
from pathlib import Path
import re
import shutil
import subprocess
import tempfile

ROOT=Path(__file__).resolve().parents[1]
SCHEMA=Path('godot/scripts/core/save_component_columns_schema.gd')
BRIDGE=Path('godot/scripts/core/save_owner_priorities.gd')
OWNER=Path('godot/scripts/core/priorities.gd')


def replace_once(source,old,new):
    assert source.count(old)==1,(old,source.count(old))
    return source.replace(old,new)


def table(source,name):
    pattern=r'(const '+re.escape(name)+r': Array = )(\[.*?\])'
    found=list(re.finditer(pattern,source,re.S)); assert len(found)==1,name
    return found[0],ast.literal_eval(found[0][2])


def edit(source,name,changes):
    match,values=table(source,name)
    for index,value in changes.items():
        values[index]=value(values[index]) if callable(value) else value
    return source[:match.start(2)]+json.dumps(values)+source[match.end(2):]


def schema_fault(source,fault):
    if fault=='key': return edit(source,'OWNER_KEYS',{11:'prioritiez'})
    if fault=='version': return edit(source,'OWNER_VERSIONS',{11:2})
    if fault=='primary': return edit(source,'OWNER_PRIMARY_COUNTS',{11:513,12:511})
    if fault=='children':
        changes={'OWNER_CHILD_COUNTS':{10:0,11:1},'OWNER_CHILD_BEGIN':{11:4},
                 'OWNER_OFFSETS':{11:lambda n:n-8},
                 'OWNER_PAYLOAD_BYTES':{10:lambda n:n-8,11:lambda n:n+8},
                 'OWNER_BLOCK_BYTES':{10:lambda n:n-8,11:lambda n:n+8}}
        for name,values in changes.items(): source=edit(source,name,values)
        return source
    if fault=='field_count':
        # Move Residents' leading u8[512] field into Priorities: +520/-520 bytes.
        changes={'OWNER_FIELD_COUNTS':{11:5,12:18},'OWNER_FIELD_BEGIN':{12:237},
                 'OWNER_OFFSETS':{12:lambda n:n+520},
                 'OWNER_PAYLOAD_BYTES':{11:lambda n:n+520,12:lambda n:n-520},
                 'OWNER_BLOCK_BYTES':{11:lambda n:n+520,12:lambda n:n-520}}
        for name,values in changes.items(): source=edit(source,name,values)
        return source
    if fault=='field_key': return edit(source,'FIELD_KEYS',{232:'_changed'})
    assert fault in ['field_type','field_extent']
    delta=1536 if fault=='field_type' else 1
    source=edit(source,'FIELD_TYPES' if fault=='field_type' else 'FIELD_COUNTS',
                {232:2 if fault=='field_type' else 513})
    for name in ['OWNER_PAYLOAD_BYTES','OWNER_BLOCK_BYTES']:
        source=edit(source,name,{11:lambda n:n+delta})
    source=edit(source,'OWNER_OFFSETS',{index:lambda n:n+delta for index in range(12,18)})
    for name in ['SECTION_BYTES','EXPECTED_SECTION_BYTES']:
        source=replace_once(source,'const '+name+': int = 12947565',
                            'const '+name+': int = '+str(12947565+delta))
    return source


def suite(code,schema_code,gate4):
    return '''extends "res://test/framework/test_case.gd"
const Schema := preload("res://scripts/core/save_component_columns_schema.gd")
const Section := preload("res://scripts/core/save_section_component_columns.gd")
const Bridge := preload("res://scripts/core/save_owner_priorities.gd")
func test_actual_metadata_gate() -> void:
	var frame: Section.FramedOwner = Section.FramedOwner.new(11)
	var bytes_before: Array[PackedByteArray] = []
	var i32_before: Array[PackedInt32Array] = []
	var i64_before: Array[PackedInt64Array] = []
	for values: PackedByteArray in frame.u8_columns: bytes_before.append(values.duplicate())
	for values: PackedInt32Array in frame.i32_columns: i32_before.append(values.duplicate())
	for values: PackedInt64Array in frame.i64_columns: i64_before.append(values.duplicate())
	var schema: Variant = Schema.schema_refusal()
	assert_equal(schema.code,&"%s","schema gate isolated")
	assert_true(Section.owner_shape_refusal(frame).is_ok(),"physically coherent frame")
	var result: Variant = Bridge.framed_refusal(frame)
	assert_equal(result.code,&"%s","real bridge refusal")
	assert_equal(result.detail.begins_with("Priorities owner11 metadata:"),%s,"gate4 prefix distinguishes schema gate")
	assert_equal(Bridge.METADATA_DETAIL_PREFIX,"Priorities owner11 metadata:","exact prefix")
	assert_true(frame.u8_columns == bytes_before,"byte inputs preserved")
	assert_true(frame.i32_columns == i32_before,"i32 inputs preserved")
	assert_true(frame.i64_columns == i64_before,"i64 inputs preserved")
	if not schema.is_ok(): assert_equal(result.detail,schema.detail,"schema detail forwarded unchanged")
	else: assert_true(true,"no schema refusal to forward")
''' % (schema_code,code,'true' if gate4 else 'false')


def execute(clone,label,expect_failure=False):
    run=subprocess.run(['godot','--headless','--path','godot','--script',
                        'res://test/priorities_metadata_probe_focus.gd'],cwd=clone,text=True,
                       stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=90)
    match=re.search(r'^1 test\(s\), 9 assertion\(s\), (\d+) failure\(s\)$',run.stdout,re.M)
    valid=match is not None and 'SCRIPT ERROR:' not in run.stdout and 'Parse Error:' not in run.stdout
    killed=bool(valid and int(match[1])>0 and run.returncode!=0)
    passed=bool(valid and int(match[1])==0 and run.returncode==0)
    assert killed if expect_failure else passed,label+'\n'+run.stdout
    return dict(case=label,assertions=9,valid_execution=valid,killed_bypass=killed,passed=passed)


def main():
    originals={p:(ROOT/p).read_bytes() for p in [SCHEMA,BRIDGE,OWNER]}
    expressions={
        'key':'Schema.owner_key(OWNER_INDEX) != OWNER_KEY',
        'version':'Schema.owner_version(OWNER_INDEX) != OWNER_VERSION',
        'primary':'Schema.primary_count(OWNER_INDEX) != OWNER_PRIMARY_COUNT',
        'children':'Schema.child_extent_count(OWNER_INDEX) != OWNER_CHILD_EXTENT_COUNT',
        'field_count':'Schema.field_count(OWNER_INDEX) != OWNER_FIELD_COUNT',
        'field_key':'Schema.field_key(OWNER_INDEX, field) != key',
        'field_type':'Schema.field_type(OWNER_INDEX, field) != Schema.TYPE_U8',
        'field_extent':'Schema.element_count(OWNER_INDEX, field) != count',
    }
    results=[]
    try:
        with tempfile.TemporaryDirectory(prefix='redwall-priorities-metadata-') as scratch:
            clone=Path(scratch)
            shutil.copytree(ROOT/'godot',clone/'godot')
            (clone/'docs').symlink_to(ROOT/'docs',target_is_directory=True)
            (clone/'assets').symlink_to(ROOT/'assets',target_is_directory=True)
            (clone/'godot/test/priorities_metadata_probe_focus.gd').write_text(
                'extends "res://test/run_tests.gd"\nfunc _discover_suites() -> PackedStringArray:\n'
                '\treturn PackedStringArray(["res://test/test_priorities_metadata_probe.gd"])\n')
            probe=clone/'godot/test/test_priorities_metadata_probe.gd'
            probe.write_text(suite('','',False))
            results.append(execute(clone,'positive-control'))
            for fault,expression in expressions.items():
                (clone/SCHEMA).write_text(schema_fault(originals[SCHEMA].decode(),fault))
                probe.write_text(suite('SAVE_COMPONENT_METADATA','',True))
                results.append(execute(clone,fault+'-fault-refused'))
                (clone/BRIDGE).write_text(replace_once(originals[BRIDGE].decode(),expression,'false'))
                results.append(execute(clone,fault+'-gate-bypassed',True))
                (clone/BRIDGE).write_bytes(originals[BRIDGE])
            (clone/SCHEMA).write_text(replace_once(originals[SCHEMA].decode(),
                'const OWNER_OFFSETS: Array = [\n\t4,','const OWNER_OFFSETS: Array = [\n\t5,'))
            probe.write_text(suite('SAVE_COMPONENT_METADATA','SAVE_COMPONENT_METADATA',False))
            results.append(execute(clone,'schema-first-forwarding'))
    finally:
        for path,original in originals.items(): assert (ROOT/path).read_bytes()==original
    assert len(results)==18
    print(json.dumps(dict(status='PASS',cases=results,source_sha256={
        str(p):hashlib.sha256(d).hexdigest() for p,d in originals.items()}),indent=2))


if __name__=='__main__':
    main()

